sys_variable_value.value:
(function (outputs, steps, params, stepResult, assertEqual) {

	var bLog = false;
	var _gtObject = new global.GlobalToolsObject();
	var _gtATF = new global.GlobalToolsATF('GlobalToolsObject', _gtObject, bLog, outputs, steps, params, stepResult, assertEqual);

	_gtATF.runATF('isObject', true, {});
	_gtATF.runATF('isObject', true, new Object());
	_gtATF.runATF('isObject', true, { 'a': 'b' });
	_gtATF.runATF('isObject', false, '');
	_gtATF.runATF('isObject', false, new String());
	_gtATF.runATF('isObject', false, 'a');
	_gtATF.runATF('isObject', false, 1);
	_gtATF.runATF('isObject', false, new Number());
	_gtATF.runATF('isObject', false, true);
	_gtATF.runATF('isObject', false, false);
	_gtATF.runATF('isObject', false, null);
	_gtATF.runATF('isObject', false, undefined);
	_gtATF.runATF('isObject', false, new Boolean());
	_gtATF.runATF('isObject', true, new Date());
	_gtATF.runATF('isObject', true, new GlideRecord('incident'));

	_gtATF.runATF('getValue', 'testvalue', 'testpath/testnode', 'testreplace', { 'testpath': { 'testnode': 'testvalue' } });
	_gtATF.runATF('getValue', 'testreplace', 'testpath_invalid/testnode', 'testreplace', { 'testpath': { 'testnode': 'testvalue' } });
	_gtATF.runATF('getValue', 'testreplace', 'testpath/testnode_invalid', 'testreplace', { 'testpath': { 'testnode': 'testvalue' } });
	_gtATF.runATF('getValue', 'testreplace', 'testpath/testnode', 'testreplace', { 'testpath': { 'testnode': '' } });
	_gtATF.runATF('getValue', 'testreplace', 'testpath/testnode', 'testreplace');
	_gtATF.runATF('getValue', 'testreplace', 'testpath/testnode', 'testreplace', {});
	_gtATF.runATF('getValue', 'testreplace', undefined, 'testreplace');

	var oObjSetValue = { 'testpath': { 'testnode': 'testvalue' } };
	_gtATF.runATF('setValue', true, 'testpath/testnode_1', 'testvalue1', oObjSetValue);
	_gtATF.runATF('getValue', 'testvalue', 'testpath/testnode', 'testreplace', oObjSetValue);
	_gtATF.runATF('getValue', 'testvalue1', 'testpath/testnode_1', 'testreplace1', oObjSetValue);

	//gs.error('tomtom: ' + JSON.stringify(oObjSetValue) + ' direct: ' + _gtObject.getValue('testpath/testnode_1', 'testreplace1', oObjSetValue));
	if (_gtObject.getValue('testpath/testnode_1', 'testreplace1', oObjSetValue) != 'testvalue1') {
		_gtATF.addError('setValue', 'Value was not set correctly.');
	} // if value not set
	_gtATF.runATF('setValue', false, '', 'testvalue1', oObjSetValue);
	_gtATF.runATF('setValue', false, '', 'testvalue1');

	_gtATF.runATF('hasValue', true, 'testpath/testnode', { 'testpath': { 'testnode': 'testvalue' } });
	_gtATF.runATF('hasValue', false, 'testpath_invalid/testnode', { 'testpath': { 'testnode': 'testvalue' } });
	_gtATF.runATF('hasValue', false, 'testpath/testnode_invalid', { 'testpath': { 'testnode': 'testvalue' } });
	_gtATF.runATF('hasValue', true, 'testpath/testnode', { 'testpath': { 'testnode': '' } });
	_gtATF.runATF('hasValue', false, 'testpath/testnode');
	_gtATF.runATF('hasValue', false, 'testpath/testnode', {});
	_gtATF.runATF('hasValue', false, undefined);

	_gtATF.runATF('deleteValue', true, 'testpath/testnode', oObjSetValue);
	_gtATF.runATF('deleteValue', false, 'testpath/testnode_invalid', oObjSetValue);
	_gtATF.runATF('hasValue', false, 'testpath/testnode', oObjSetValue);

	var oObjDeepMerge1 = { 'testpath': { 'testnode': 'testvalue', 'testnode_1': 'testvalue_1' } };
	var oObjDeepMerge2 = { 'testpath': { 'testnode': 'testvalue_override', 'testnode_2': 'testvalue_2' } };
	_gtATF.runATF('deepMerge', { 'testpath': { 'testnode': 'testvalue_override', 'testnode_1': 'testvalue_1', 'testnode_2': 'testvalue_2' } }, oObjDeepMerge1, oObjDeepMerge2);

	oObjDeepMerge1 = { 'testpath': ['array_value_1', 'array_value_2'] };
	oObjDeepMerge2 = { 'testpath': ['array_value_1', 'array_value_3'] };
	_gtATF.runATF('deepMerge', { 'testpath': ['array_value_1', 'array_value_3'] }, oObjDeepMerge1, oObjDeepMerge2);
	oObjDeepMerge1 = { 'testpath': ['array_value_1', 'array_value_2'] };
	oObjDeepMerge2 = { 'testpath': ['array_value_1', 'array_value_3'] };
	_gtATF.runATF('deepMerge', { 'testpath': ['array_value_1', 'array_value_2', 'array_value_3'] }, oObjDeepMerge1, oObjDeepMerge2, true);
	oObjDeepMerge1 = { 'testpath': true };
	oObjDeepMerge2 = { 'testpath1': false };
	_gtATF.runATF('deepMerge', { 'testpath': true, 'testpath1': false }, oObjDeepMerge1, oObjDeepMerge2);

	_gtATF.runATF('getDepth', -1, 'teststring');
	_gtATF.runATF('getDepth', 0, {});
	_gtATF.runATF('getDepth', 1, { 'testpath': 'testvalue' });
	_gtATF.runATF('getDepth', 1, { 'testpath': {} });
	_gtATF.runATF('getDepth', 2, { 'testpath': { 'testnode': 'testvalue' } });
	_gtATF.runATF('getDepth', 3, { 'sugus0': 'sugus1', 'testpath': { 'testnode': 'testvalue' }, 'sugus2': {'sugus3': {'sugus4': 'sugus5', 'array1': [{'sugus7': 'sugus8'}]}}, 'sugus6': 6});
	_gtATF.runATF('getDepth', 4, { 'sugus0': 'sugus1', 'testpath': { 'testnode': 'testvalue' }, 'sugus2': {'sugus3': {'sugus4': 'sugus5', 'sugus6': {'sugus7': 'sugus8'}}}, 'sugus6': 6});

	// Cannot test cyclic value because of earlier check: Cyclic {0} value not allowed.
	//var oObjRecursive = {'sugus0': 'sugus2'};
	//oObjRecursive['sugus1'] = oObjRecursive;
	//_gtATF.runATF('getDepth', -2, oObjRecursive);

	_gtATF.runATF('parseJSON', undefined);
	_gtATF.runATF('parseJSON', undefined, 'teststring');
	_gtATF.runATF('parseJSON', undefined, 1);
	_gtATF.runATF('parseJSON', {}, '{}');
	_gtATF.runATF('parseJSON', {'test': 'sugus0'}, '{"test": "sugus0"}');

	_gtATF.runATF('getJSONPath', undefined);
	_gtATF.runATF('getJSONPath', undefined, 'teststring');
	_gtATF.runATF('getJSONPath', undefined, 1);
	_gtATF.runATF('getJSONPath', undefined, '{}');
	_gtATF.runATF('getJSONPath', undefined, {});
	_gtATF.runATF('getJSONPath', /object GlideJsonPath/i, {"test": "sugus0"});

	return _gtATF.endATF();

})(outputs, steps, params, stepResult, assertEqual);
